  "faqs": [
    {
      "q": "Do Indian citizens need a visa for Ireland?",
      "a": "Yes. Indian passport holders generally need an Irish visa before travelling to Ireland."
    },
    {
      "q": "Is Ireland part of the Schengen Area?",
      "a": "No. Ireland is not part of the Schengen Area, so an Irish visa is separate from a Schengen visa."
    },
    {
      "q": "Which visa should I apply for tourism?",
      "a": "For holidays or sightseeing trips of less than 90 days, applicants generally apply for a Short Stay 'C' Visit Tourist Visa through the AVATS online system."
    },
    {
      "q": "How long can I stay in Ireland on a Short Stay 'C' visa?",
      "a": "A Short Stay 'C' visa can allow a stay of up to 90 days. The actual permission to stay is decided by an immigration officer when you arrive."
    },
    {
      "q": "How long does an Ireland tourist visa take to process?",
      "a": "Applicants can generally expect a decision around 8 weeks after the required documents are received. Processing times can vary depending on the application and visa office."
    },
    {
      "q": "How early should I apply for an Ireland visa?",
      "a": "It is recommended to prepare and submit your application well in advance, ideally around 3 months before your planned travel date."
    },
    {
      "q": "Do Indian applicants need to provide biometrics?",
      "a": "Yes. Applicants residing in India are generally required to provide fingerprints as part of the Irish visa process, subject to applicable exemptions."
    },
    {
      "q": "Do I need confirmed flight tickets before applying?",
      "a": "You should provide evidence of your intended travel plans, but it is advisable not to purchase non-refundable travel tickets before receiving a visa decision."
    },
    {
      "q": "Can I get a multiple-entry Ireland tourist visa?",
      "a": "Multiple-entry visas are granted only in certain circumstances. Applicants need to meet the relevant eligibility requirements and provide supporting evidence."
    },
    {
      "q": "Can I travel to Northern Ireland with an Irish visa?",
      "a": "No. Northern Ireland is part of the United Kingdom and follows UK immigration rules. An Irish visa does not automatically permit entry into Northern Ireland."
    },
    {
      "q": "Can I travel to the UK with an Ireland visa?",
      "a": "An Irish visa does not automatically permit entry into the UK. Separate UK immigration requirements apply, although certain eligible Indian nationals may qualify under the British-Irish Visa Scheme."
    },
    {
      "q": "Is travel insurance mandatory for an Ireland tourist visa?",
      "a": "Travel insurance is recommended for your trip. Ireland is not part of the Schengen Area, so the Schengen insurance requirement does not apply."
    },
    {
      "q": "Can additional documents be requested?",
      "a": "Yes. The Irish visa office may request additional documents or information if required to assess your application."
    },
    {
      "q": "Does an Ireland visa guarantee entry?",
      "a": "No. A visa allows you to travel to Ireland, but final permission to enter and the length of stay are decided by an immigration officer at border control."
    },
    {
      "q": "Does having a visa guarantee approval?",
      "a": "No. Every application is assessed individually based on the documents, circumstances and evidence provided."
    }
  ],

