  "faqs": [
    {
      "q": "Do Indians need a visa for Norway?",
      "a": "Yes. Indian passport holders generally need a Schengen visitor visa for short stays in Norway."
    },
    {
      "q": "How long does it take to process a Norway visa?",
      "a": "The normal processing time is around 15 working days after the application is received. Some applications may take longer, and certain cases can take up to 45 working days."
    },
    {
      "q": "How long can I stay in Norway on a Schengen visa?",
      "a": "A Schengen visitor visa can allow a stay of up to 90 days within a 180-day period, subject to the conditions stated on the visa."
    },
    {
      "q": "Is travel insurance mandatory for a Norway visa?",
      "a": "Yes. Travel medical insurance with minimum coverage of €30,000 is required for the entire planned stay and must be valid across the Schengen area."
    },
    {
      "q": "Do I need to provide biometrics for a Norway visa?",
      "a": "Applicants generally need to provide fingerprints and a photograph in person. Previous fingerprints may be reused where permitted under the applicable rules."
    },
    {
      "q": "Where do I submit my Norway visa application in India?",
      "a": "Norway Schengen visa applications in India are submitted through VFS Global Application Centres and processed by the Norwegian authorities."
    },
    {
      "q": "Can I apply without confirmed flight tickets?",
      "a": "A flight reservation or itinerary can generally be submitted as part of your travel plans. It is advisable to avoid purchasing non-refundable tickets before your visa is granted."
    },
    {
      "q": "Do I need to show proof of funds?",
      "a": "Yes. You need to demonstrate sufficient funds for your planned stay. Sponsorship documents may also be relevant where applicable."
    },
    {
      "q": "Can I visit other Schengen countries with a Norway visa?",
      "a": "Yes. A Norway-issued Schengen visa can generally allow travel to other Schengen countries, subject to the visa conditions and main-destination rules."
    },
    {
      "q": "Can Vision Visa help with my Norway visa application?",
      "a": "Yes. Vision Visa can assist with document guidance, document review, application preparation and support throughout your Norway Schengen visa process."
    },
    {
      "q": "Who makes the final decision on my Norway visa?",
      "a": "The final decision is made by the competent Norwegian authorities. Vision Visa assists with preparation but cannot guarantee visa approval."
    }
  ],

