  "faqs": [
    {
      "q": "How long does it take to process a USA B1/B2 visa?",
      "a": "There is no single fixed processing time. Appointment availability varies by location and season, and some applications may require additional administrative processing after the interview."
    },
    {
      "q": "What is a B1/B2 Visitor Visa?",
      "a": "A B1/B2 visa is a nonimmigrant visitor visa for eligible temporary business and tourism purposes, including holidays and visits to family or friends."
    },
    {
      "q": "Do I need to complete the DS-160?",
      "a": "Yes. Applicants for a U.S. nonimmigrant visa generally need to complete and submit the DS-160 online and bring the confirmation page as instructed."
    },
    {
      "q": "Do I need to attend a visa interview?",
      "a": "Interviews are generally required for U.S. visitor visa applicants, although limited exceptions may apply. A consular officer may require an interview even where an exception could otherwise apply."
    },
    {
      "q": "Is travel insurance mandatory for a USA visitor visa?",
      "a": "Travel insurance is not generally mandatory for a B1/B2 visitor visa, but suitable travel insurance is strongly recommended."
    },
    {
      "q": "Do I need confirmed flight tickets before applying?",
      "a": "No. A confirmed flight ticket is not a standard required document for a B1/B2 visa. It is generally advisable to avoid non-refundable travel commitments before visa approval."
    },
    {
      "q": "Do I need an invitation letter from someone in the USA?",
      "a": "No. An invitation letter or Affidavit of Support is not required for a visitor visa application. If relevant, information about your host or purpose of visit may still support your application."
    },
    {
      "q": "What financial documents should I provide?",
      "a": "You should demonstrate that you can cover the reasonable costs of your trip. Bank statements, employment records, salary information, and other financial evidence may help support your application."
    },
    {
      "q": "What documents can show my intention to return to India?",
      "a": "Employment, family relationships, financial circumstances, business commitments, and other genuine ties to India may help demonstrate your intention to return after your temporary visit."
    },
    {
      "q": "Can Vision Visa assist with my USA visa application?",
      "a": "Yes. Vision Visa can assist with document verification, DS-160 preparation, application guidance, and interview preparation. The final visa decision is made solely by the U.S. consular officer."
    },
    {
      "q": "How is the USA visa decision made?",
      "a": "The U.S. consular officer assesses whether the applicant qualifies for the visa under U.S. immigration law, including the purpose of travel, circumstances, and eligibility for a temporary visit."
    },
    {
      "q": "What happens after the USA visa interview?",
      "a": "The application may be approved, refused, or placed in administrative processing. The next steps depend on the individual application and consular decision."
    }
  ],

